sketch:
tabulate⁻ : ∀ {n} {f : Fin n → A} → Any P (tabulate f) → ∃ λ i → P (f i)
-- Base case: n = 0. The type Fin 0 has no elements, so tabulate f is the empty list and Any P [] has no proof. The case is impossible.
tabulate⁻ {zero} {f} p = {!!}
-- Inductive case: let n = suc m. By the lemma tabulateSuc, tabulate f is f zero followed by tabulate (f ∘ suc).
-- Case where the head satisfies P: we have P (f zero). Take i = zero.
tabulate⁻ {suc m} {f} (here px) = {!!}
-- Case where the tail satisfies Any P: the induction hypothesis applied to f ∘ suc gives j with P ((f ∘ suc) j). Take i = suc j, since (f ∘ suc) j = f (suc j).
tabulate⁻ {suc m} {f} (there pxs) = {!!}

lemmas.tabulateSuc:
{A.a : Level} {A = A₁ : Set A.a} {m : Data.Nat.Base.ℕ}
(f₁ : Fin (suc m) → A₁) →
tabulate f₁ ≡ f₁ zero ∷ tabulate (λ j → f₁ (suc j))

sketch:
tabulate⁻ : ∀ {n} {f : Fin n → A} → Any P (tabulate f) → ∃ λ i → P (f i)
-- Base case: n = 0. The type Fin 0 has no elements, so tabulate f is the empty list. The predicate Any P [] has no constructors, so this case is impossible and the existential follows vacuously.
tabulate⁻ {n = zero} {f = f} p = {!!}
-- Inductive case: let n = suc m and assume the induction hypothesis for m, generalised over f. By the lemma tabulateSuc, tabulate f is f zero followed by tabulate f′, where f′ j = f (suc j).
-- Case where the head satisfies P: we have P (f zero). Take i = zero : Fin (suc m). Then P (f i) holds.
tabulate⁻ {n = suc m} {f = f} (here px) = {!!}
-- Case where the tail satisfies Any P: by the induction hypothesis applied to f′, there exists j : Fin m with P (f′ j). Since f′ j = f (suc j), take i = suc j : Fin (suc m). Then P (f i) holds.
tabulate⁻ {n = suc m} {f = f} (there pxs) = {!!}

lemmas.tabulateSuc:
{A.a : Level} {A = A₁ : Set A.a} {n : Data.Nat.Base.ℕ}
{f = f₁ : Fin (suc n) → A₁} →
tabulate f₁ ≡ f₁ zero ∷ tabulate (λ i → f₁ (suc i))

sketch:
tabulate⁻ : ∀ {n} {f : Fin n → A} → Any P (tabulate f) → ∃ λ i → P (f i)
-- [case] Base case n = 0. The list tabulate f is empty, so Any P [] has no proof and the implication holds vacuously.
tabulate⁻ {n = zero} {f = f} p = {!!}
-- [case] Inductive case n = suc m. By the lemma tabulateSuc, tabulate f is f zero followed by tabulate g, where g i = f (suc i).
-- [case] Sub-case where P (f zero) holds. Take the index zero, so P (f zero) is the required conclusion.
tabulate⁻ {n = suc m} {f = f} (here px) = {!!}
-- [case] Sub-case where Any P (tabulate g) holds. Apply the induction hypothesis to g, obtain j with P (g j), and take the index suc j, since f (suc j) = g j.
tabulate⁻ {n = suc m} {f = f} (there pxs) = {!!}
